let doc=fs.readFileSync(DOC_PATH,'utf8'); doc=doc.replace('Produksjonen står på 94 av 230 etter at Byhistorie og stedsendring er fullført til 10/10 med en kombinasjon av eksisterende validerte claims og målrettet ny evidens for bygrense og gentrifisering.','Produksjonen står på 102 av 230 etter at Makt, stat og institusjoner er fullført til 10/10 med gjenbruk der evidensen allerede var sterk og målrettet ny evidens for embetsverk, rettsstat og register/overvåking.'); doc=doc.replace('- Byhistorie og stedsendring V1: **7** nye kvalifiserende teoriobjekter, **6** nye claims, **4** nye kilder, **10** nye place-evidence-lenker og **0** nye cases; grense/innlemmelse og gentrifisering får målrettet ny evidens, mens de øvrige fem objektene kombinerer gjenbruk med de nye Nydalen-claimene der det styrker anvendelsen. Regulering/plan-objektet dokumenterer plan og fysisk gjennomføring, ikke ekspropriasjonsvedtak eller erstatning, og gentrifiseringsobjektet dokumenterer sosialt endringsmønster og eiendomsdrevet funksjonsskifte uten å hevde individnivå-fortrengning.\n','- Byhistorie og stedsendring V1: **7** nye kvalifiserende teoriobjekter, **6** nye claims, **4** nye kilder, **10** nye place-evidence-lenker og **0** nye cases; grense/innlemmelse og gentrifisering får målrettet ny evidens, mens de øvrige fem objektene kombinerer gjenbruk med de nye Nydalen-claimene der det styrker anvendelsen. Regulering/plan-objektet dokumenterer plan og fysisk gjennomføring, ikke ekspropriasjonsvedtak eller erstatning, og gentrifiseringsobjektet dokumenterer sosialt endringsmønster og eiendomsdrevet funksjonsskifte uten å hevde individnivå-fortrengning.\n- Makt, stat og institusjoner V1: **8** nye kvalifiserende teoriobjekter, **9** nye claims, **6** nye kilder, **9** nye place-evidence-lenker og **0** nye cases; fem objekter bygger hovedsakelig på claim-gjenbruk, mens embetsverk/byråkrati, lov/domstol/rettsstat og register/overvåking/disiplin får målrettet ny evidens. Register-objektet skiller eksplisitt demokratisk sikkerhetsovervåking fra nazistisk fange-klassifikasjon, og statskapasitet avgrenses til dokumentert fiskal, tilsynsmessig og militær kapasitet.\n'); doc=doc.replace('- Totalt: **94 av 230** teoriobjekter (**40.9 %**).','- Totalt: **102 av 230** teoriobjekter (**44.3 %**).'); doc=doc.replace('- Gjenstående teoriobjekter: **136**.','- Gjenstående teoriobjekter: **128**.'); fs.writeFileSync(DOC_PATH,doc);

